  ["env", "env | rg '^(ARCHON_HORIZON|HORIZON_)' | sort", "/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild"]
];
const rs = await Promise.all(cmds.map(async ([name,cmd,workdir]) => [name, await tools.exec_command({cmd,workdir,yield_time_ms:10000,max_output_tokens:30000})]));
for (const [name,r] of rs) { text(`--- ${name} ---\n${r.output}`); }

const base="/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects";
const cmds=[
 ["decls",`rg -n --glob '*.lean' '(canonicalRankOneAbelIso|rankOneAbelIso|pic0_representableBy|PicRepDatum|JacobianData|jacobianData|PicRankOneOpen|IsOpen)' '${base}/Algebraic-Jacobian-Challenge-Rebuild' '${base}/Algebraic-Jacobian-Challenge'`],
 ["sorries",`rg -n --glob '*.lean' '\\b(sorry|axiom)\\b' '${base}/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian' '${base}/Algebraic-Jacobian-Challenge/AJC'`],
 ["roots",`rg -n --glob '*.lean' '^import .*Pic0|^import .*PicRep|^import .*Challenge|^import .*JacobianData|^import .*CriticalPath' '${base}/Algebraic-Jacobian-Challenge-Rebuild' '${base}/Algebraic-Jacobian-Challenge'`],
 ["files",`rg --files '${base}/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian' '${base}/Algebraic-Jacobian-Challenge/AJC' | rg '(Pic0CriticalPath|Pic0RankOne|PicRepDatum|Challenge|JacobianData|AlgebraicJacobian\\.lean)$|Pic0CriticalPath|PicRepDatum'`]
];
const rs=await Promise.all(cmds.map(async ([n,cmd])=>[n,await tools.exec_command({cmd,workdir:base,yield_time_ms:10000,max_output_tokens:30000})]));
for(const [n,r] of rs) text(`--- ${n} ---\n${r.output}`);

